import asyncio
import httpx
import json
import logging
import re
from dataclasses import dataclass
from typing import Optional

logger = logging.getLogger(__name__)


@dataclass
class Quiz:
    """Structured quiz generated by AI."""
    question: str
    options: list[str]
    correct_index: int

    @property
    def correct_option(self) -> str:
        return self.options[self.correct_index]


class AIServiceError(Exception):
    def __init__(self, message: str, category: str = "EXTERNAL", status_code: int = 500):
        super().__init__(message)
        self.category = category
        self.status_code = status_code


class AIService:
    def __init__(self):
        self.api_url = "https://opencode.ai/zen/v1/chat/completions"
        self.model = "big-pickle"
        self.timeout = 60.0
        self.max_retries = 3
        self.base_delay = 1.0

    # ── public ──────────────────────────────────────────────

    async def generate_quiz(self, topic: str, feedback: Optional[str] = None) -> Quiz:
        """Generate a quiz from a topic. Retries formatting if AI returns bad JSON."""
        system = self._system_prompt()
        user = self._user_prompt(topic, feedback)

        raw = await self._call_api_with_retry(system, user)
        quiz = self._try_parse_quiz(raw)

        if quiz is None:
            # AI returned malformed JSON — ask it to fix
            logger.warning("AI returned unparseable response, requesting reformat")
            fix_prompt = (
                "Tu respuesta anterior no era JSON válido. "
                "Aquí está tu respuesta:\n\n"
                f"{raw}\n\n"
                "Por favor, reformátala EXACTAMENTE como este ejemplo, "
                "sin texto adicional, sin markdown, sin ```:\n"
                '{"question":"pregunta aquí","options":["A","B","C","D"],"correct":0}'
            )
            raw2 = await self._call_api_with_retry(system, fix_prompt)
            quiz = self._try_parse_quiz(raw2)

            if quiz is None:
                raise AIServiceError(
                    "La IA no pudo generar un quiz con formato válido. Intenta de nuevo.",
                    category="PARSE_ERROR",
                    status_code=502,
                )

        return quiz

    # ── JSON parsing with regex fallback ────────────────────

    def _try_parse_quiz(self, text: str) -> Optional[Quiz]:
        """Try to parse AI response into a Quiz. Returns None on failure."""
        # Strip markdown code fences if present
        cleaned = re.sub(r"```(?:json)?\s*", "", text).strip().rstrip("`")

        # Try direct parse
        try:
            data = json.loads(cleaned)
            return self._quiz_from_dict(data)
        except (json.JSONDecodeError, KeyError, ValueError):
            pass

        # Try to extract JSON object from surrounding text
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if match:
            try:
                data = json.loads(match.group())
                return self._quiz_from_dict(data)
            except (json.JSONDecodeError, KeyError, ValueError):
                pass

        return None

    def _quiz_from_dict(self, data: dict) -> Quiz:
        question = str(data["question"]).strip()
        options = [str(o).strip() for o in data["options"]]
        correct = int(data["correct"])

        if not question:
            raise ValueError("empty question")
        if len(options) < 2:
            raise ValueError("need at least 2 options")
        if not (0 <= correct < len(options)):
            raise ValueError(f"correct index {correct} out of range")

        return Quiz(question=question, options=options, correct_index=correct)

    # ── API calls ───────────────────────────────────────────

    async def _call_api_with_retry(self, system_prompt: str, user_prompt: str) -> str:
        last_exception = None
        for attempt in range(self.max_retries + 1):
            try:
                return await self._call_api(system_prompt, user_prompt)
            except httpx.HTTPStatusError as e:
                last_exception = e
                if e.response.status_code == 429 and attempt < self.max_retries:
                    retry_after = e.response.headers.get("Retry-After")
                    delay = float(retry_after) if retry_after else self.base_delay * (2 ** attempt)
                    logger.info("Rate limited, retrying in %ss (%d/%d)", delay, attempt + 1, self.max_retries)
                    await asyncio.sleep(delay)
                    continue
                raise
            except (httpx.TimeoutException, httpx.NetworkError) as e:
                last_exception = e
                if attempt < self.max_retries:
                    delay = self.base_delay * (2 ** attempt)
                    logger.info("Transient error, retrying in %ss (%d/%d)", delay, attempt + 1, self.max_retries)
                    await asyncio.sleep(delay)
                    continue
                raise
        if last_exception:
            raise last_exception
        raise AIServiceError("AI service failed after retries", category="EXTERNAL", status_code=502)

    async def _call_api(self, system_prompt: str, user_prompt: str) -> str:
        headers = {
            "Content-Type": "application/json",
            "User-Agent": "opencode/1.18.15",
        }
        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "temperature": 0.7,
        }

        async with httpx.AsyncClient(timeout=self.timeout) as client:
            resp = await client.post(self.api_url, headers=headers, json=payload)
            resp.raise_for_status()
            data = resp.json()

            if "choices" not in data or not data["choices"]:
                raise ValueError("Invalid response: missing 'choices'")
            content = data["choices"][0].get("message", {}).get("content", "")
            if not isinstance(content, str) or not content.strip():
                raise ValueError("Invalid response: empty content")
            return content.strip()

    # ── prompts ─────────────────────────────────────────────

    def _system_prompt(self) -> str:
        return (
            "Eres un experto en crear quizzes de español para estudiantes. "
            "Generas preguntas de opción múltiple con UNA respuesta correcta.\n\n"
            "REGLAS:\n"
            "- Responde SOLO con JSON válido, sin texto adicional\n"
            "- El JSON debe tener esta forma exacta:\n"
            '{"question":"...","options":["A","B","C","D"],"correct":0}\n'
            "- 'question' = la pregunta clara y concisa\n"
            "- 'options' = entre 3 y 4 opciones de respuesta\n"
            "- 'correct' = índice (0-based) de la respuesta correcta\n"
            "- Todo en español\n"
            "- Las preguntas deben ser educativas y precisas\n"
            "- Las opciones incorrectas deben ser creíbles (errores comunes de estudiantes)"
        )

    def _user_prompt(self, topic: str, feedback: Optional[str] = None) -> str:
        if feedback:
            return (
                f"Tema: {topic}\n\n"
                f"Mejora sugerida: {feedback}\n\n"
                "Genera un quiz mejorado sobre este tema."
            )
        return f"Crea un quiz sobre: {topic}"
